import { step, wander, glide } from "../world/movement.js";
import { bounce } from "../world/bounds.js";
import { TICKS_PER_SECOND, seconds } from "../world/time.js";

const SHELL = "coral";
const TAIL = "darkorange";
const EYE = "black";
const DART_INTERVAL = seconds(2);
const DART_COST = ENERGY_MAX / 20;
const DART_PUSH = 2.5;

export function spawn() {
  return {
    energy: ENERGY_MAX,
    dartTimer: Math.floor(Math.random() * DART_INTERVAL),
  };
}

export function update(shrimp, world) {
  shrimp.dartTimer += 1;

  if (shrimp.dartTimer >= DART_INTERVAL) {
    shrimp.dartTimer = 0;
    drain(shrimp, DART_COST);
    wander(shrimp, DART_PUSH);
  }

  glide(shrimp, 0.92);
  step(shrimp);
  bounce(shrimp);
}

export function draw(shrimp, pen) {
  if (shrimp.vx < 0) {
    pen.flip();
  }

  pen.fill(SHELL);
  pen.ellipse(0, 0, 18, 10);

  pen.fill(TAIL);
  pen.poly([-10, 0, -24, -8, -24, 8]);

  pen.fill(EYE);
  pen.circle(8, -2, 2);
