const BODY = "coral";
const EYE = "black";

const DART_INTERVAL = seconds(2);
const DART_ENERGY = 5;

export function spawn() {
  return { vx: 0, vy: 0, energy: ENERGY_MAX };
}

export function update(shrimp, world) {
  if (shrimp.age % DART_INTERVAL === 0) {
    wander(shrimp, 3);
    drain(shrimp, DART_ENERGY);
  }
  glide(shrimp, 0.96);
  step(shrimp);
  bounce(shrimp);
}

