  pen.line(-12, 4, -20, 10);
  pen.line(-8, 4, -14, 12);
  pen.line(12, 4, 20, 10);
  pen.line(8, 4, 14, 12);

  pen.fill(EYE);
  pen.circle(11, -3, 2);
}
